-- Migration number: 0001 	 Create businesses, staff users, and menu tables
--
-- Conventions:
--   * IDs are random text IDs generated by the app (crypto.randomUUID()), never sequential.
--   * Money is stored as integer centavos.
--   * Timestamps are UTC ISO-8601 strings.
--   * Every tenant table carries business_id. Child tables use composite foreign keys
--     (parent_id, business_id) so the database itself rejects links across stores.

CREATE TABLE businesses (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  slug        TEXT NOT NULL UNIQUE COLLATE NOCASE,
  logo_key    TEXT,                                   -- R2 object key
  banner_key  TEXT,                                   -- R2 object key
  about       TEXT NOT NULL DEFAULT '',
  hours       TEXT NOT NULL DEFAULT '[]',             -- JSON, validated with Zod
  timezone    TEXT NOT NULL DEFAULT 'Asia/Manila',
  is_open     INTEGER NOT NULL DEFAULT 0 CHECK (is_open IN (0, 1)),
  settings    TEXT NOT NULL DEFAULT '{}',             -- JSON, validated with Zod
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE staff_users (
  id           TEXT PRIMARY KEY,
  business_id  TEXT NOT NULL REFERENCES businesses (id) ON DELETE CASCADE,
  email        TEXT NOT NULL COLLATE NOCASE,
  role         TEXT NOT NULL DEFAULT 'owner' CHECK (role IN ('owner')),
  created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (business_id, email)
);

CREATE INDEX idx_staff_users_email ON staff_users (email);

CREATE TABLE menu_categories (
  id           TEXT PRIMARY KEY,
  business_id  TEXT NOT NULL REFERENCES businesses (id) ON DELETE CASCADE,
  name         TEXT NOT NULL,
  sort_order   INTEGER NOT NULL DEFAULT 0,
  created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (id, business_id)
);

CREATE INDEX idx_menu_categories_business ON menu_categories (business_id, sort_order);

CREATE TABLE menu_items (
  id            TEXT PRIMARY KEY,
  business_id   TEXT NOT NULL REFERENCES businesses (id) ON DELETE CASCADE,
  category_id   TEXT,
  name          TEXT NOT NULL,
  description   TEXT NOT NULL DEFAULT '',
  price         INTEGER NOT NULL CHECK (price >= 0),  -- centavos
  photo_key     TEXT,                                 -- R2 object key
  is_available  INTEGER NOT NULL DEFAULT 1 CHECK (is_available IN (0, 1)),
  sort_order    INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (id, business_id),
  FOREIGN KEY (category_id, business_id)
    REFERENCES menu_categories (id, business_id) ON DELETE RESTRICT
);

CREATE INDEX idx_menu_items_business ON menu_items (business_id, category_id, sort_order);

CREATE TABLE option_groups (
  id           TEXT PRIMARY KEY,
  business_id  TEXT NOT NULL REFERENCES businesses (id) ON DELETE CASCADE,
  item_id      TEXT NOT NULL,
  name         TEXT NOT NULL,
  required     INTEGER NOT NULL DEFAULT 0 CHECK (required IN (0, 1)),
  max_choices  INTEGER NOT NULL DEFAULT 1 CHECK (max_choices >= 1),
  sort_order   INTEGER NOT NULL DEFAULT 0,
  UNIQUE (id, business_id),
  FOREIGN KEY (item_id, business_id)
    REFERENCES menu_items (id, business_id) ON DELETE CASCADE
);

CREATE INDEX idx_option_groups_item ON option_groups (business_id, item_id, sort_order);

CREATE TABLE options (
  id           TEXT PRIMARY KEY,
  business_id  TEXT NOT NULL REFERENCES businesses (id) ON DELETE CASCADE,
  group_id     TEXT NOT NULL,
  name         TEXT NOT NULL,
  extra_price  INTEGER NOT NULL DEFAULT 0 CHECK (extra_price >= 0),  -- centavos
  sort_order   INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (group_id, business_id)
    REFERENCES option_groups (id, business_id) ON DELETE CASCADE
);

CREATE INDEX idx_options_group ON options (business_id, group_id, sort_order);
